package ama.transcript;

import ama.canonical.CanonicalValue;
import ama.config.ConfigBindings;
import ama.contract.MinutesContracts.*;
import java.util.*;
import static ama.canonical.CanonicalValue.*;
import static ama.contract.MinutesContracts.*;
import static ama.contract.MinutesContracts.FailureCode.*;

/** Pure material text projection keyed by the same exact catalog aliases as model evidence. */
final class MaterialMinutesContext {
 static List<CanonicalValue> render(List<FullRow> rows,ConfigBindings.ValidatedGenerationBinding binding,Set<CanonicalValue> excluded){var out=new ArrayList<CanonicalValue>();for(var source:binding.catalog().sources()){var fact=source.fact();if(fact.role()!=Role.BACKGROUND||excluded.contains(ama.minutes.contract.ContractValues.locator(fact.locator())))continue;String document=switch(fact.sourceVersion()){case FileVersion f->f.parsedDocumentId();case KnowledgeVersion k->k.parsedDocumentId();default->throw fail(PROVENANCE_UNAVAILABLE);};var units=rows.stream().filter(r->r.table()==Table.PARSED_UNIT&&document.equals(r.string("document_id"))).sorted(Comparator.comparingLong(r->r.number("ordinal"))).toList();String body;if(fact.locator() instanceof KnowledgeLocator)body=String.join("\n\n",units.stream().map(r->r.string("body")).toList());else{var selected=units.stream().filter(r->fact.locator() instanceof PageLocator pageLocator&&Objects.equals(r.nullableNumber("page_no"),pageLocator.pageNo())||fact.locator() instanceof ParagraphLocator paragraphLocator&&Objects.equals(r.nullableNumber("paragraph_no"),paragraphLocator.paragraphNo())&&Objects.equals(r.nullableString("section_path"),paragraphLocator.sectionPath())).toList();require(selected.size()==1,PROVENANCE_UNAVAILABLE);body=selected.getFirst().string("body");}out.add(object(field("sourceId",string(source.sourceId())),field("locator",ama.minutes.contract.ContractValues.locator(fact.locator())),field("sourceVersion",ama.minutes.contract.ContractValues.sourceVersion(fact.sourceVersion())),field("body",string(body))));}return List.copyOf(out);}
 static Locator locator(FullRow row){return switch(row.string("kind")){case "TRANSCRIPT"->new TranscriptLocator(row.string("transcript_revision_id"),row.string("segment_id"));case "PDF_PAGE","PPT_PAGE"->new PageLocator(PageKind.valueOf(row.string("kind")),row.string("file_id"),row.number("page_no"));case "WORD_PARAGRAPH","TEXT_PARAGRAPH"->new ParagraphLocator(ParagraphKind.valueOf(row.string("kind")),row.string("file_id"),row.number("paragraph_no"),row.nullableString("section_path"));case "KNOWLEDGE_VERSION"->new KnowledgeLocator(row.string("material_revision_id"));default->throw fail(CAPABILITY_UNAVAILABLE);};}
 static FullRow row(String id,String meeting,Locator locator){String kind;String revision=null,segment=null,file=null,material=null,section=null;Long page=null,paragraph=null;switch(locator){case TranscriptLocator t->{kind="TRANSCRIPT";revision=t.transcriptRevisionId();segment=t.segmentId();}case PageLocator p->{kind=p.kind().name();file=p.fileId();page=p.pageNo();}case ParagraphLocator p->{kind=p.kind().name();file=p.fileId();paragraph=p.paragraphNo();section=p.sectionPath();}case KnowledgeLocator k->{kind="KNOWLEDGE_VERSION";material=k.materialRevisionId();}default->throw fail(CAPABILITY_UNAVAILABLE);}var cells=new ArrayList<Cell>();for(Object value:new Object[]{id,meeting,kind,revision,segment,file,material,page,paragraph,section,null,null})cells.add(value==null?new NullCell():value instanceof Long n?cell(n):cell((String)value));return new FullRow(Table.SOURCE_LOCATOR,cells);}
}
